+  },
+  {
+    question: "Can cats really see in the dark?",
+    answer:
+      "Not in complete darkness, but cats see far better than humans in low light. Their eyes have a <strong>tapetum lucidum</strong> — a reflective layer behind the retina that amplifies incoming light — and a higher density of rod cells. This gives them roughly <strong>six to eight times</strong> better night vision than humans.",
+  },
+  {
+    question: "Why do cats bring dead animals home?",
+    answer:
+      "This is a gift — genuinely. Cats are natural hunters and, especially with humans they're bonded to, they may be trying to share the bounty or 'teach' you to hunt. Mother cats do this with kittens; domestic cats extend the behaviour to their human family.",
+  },
+  {
+    question: "Are cats solitary animals?",
+    answer:
+      "While cats are facultatively solitary hunters (unlike dogs), they are not antisocial. Feral cats often form colonies centred around food sources, and domestic cats can form strong social bonds with humans and other pets. Each cat has an individual personality — some crave company, others prefer independence.",
+  },
+  {
+    question: "Why do cats knead with their paws?",
+    answer:
+      "Kneading — the rhythmic pushing of paws against a soft surface — begins in kittenhood to stimulate a mother's milk flow. In adult cats it's a deeply ingrained comfort behaviour associated with warmth, safety, and contentment. If your cat kneads you, consider it a compliment.",
+  },
+  {
+    question: "What does it mean when a cat slow-blinks at you?",
+    answer:
+      "A slow blink from a cat is often called a <strong>'cat kiss'</strong>. It signals trust and relaxed affection — the cat is comfortable enough to briefly close its eyes around you. You can return the gesture; many cats will slow-blink back, reinforcing the social bond.",
+  },
+];
+
+function ChevronIcon() {
+  return `
+    <svg viewBox="0 0 24 24" aria-hidden="true">
+      <polyline points="6 9 12 15 18 9"></polyline>
+    </svg>
+  `;
+}
+
+function FAQItem({ question, answer, index }) {
+  return `
+    <div class="example" id="faq-${index}" role="region">
+      <button
+        class="faq-trigger"
+        aria-expanded="false"
+        aria-controls="details-${index}"
+        id="trigger-${index}"
